<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$event->title}} | Net-Works</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font:15px Arial;color:#18243a}header{background:#fff;border-bottom:1px solid #e2e8f0;padding:18px max(24px,calc((100% - 1120px)/2));font-size:22px;font-weight:800}.wrap{max-width:1120px;margin:34px auto;padding:0 20px}.hero{background:linear-gradient(135deg,#173f8f,#7050d5);border-radius:16px;color:#fff;padding:35px}.hero h1{font-size:36px;margin:8px 0}.layout{display:grid;grid-template-columns:minmax(0,1fr) 410px;gap:22px;margin-top:22px}.card{background:#fff;border:1px solid #e1e7ef;border-radius:14px;padding:22px;margin-bottom:16px}.card h2{margin:0 0 16px;font-size:19px}.choice{display:grid;grid-template-columns:1fr 100px;gap:14px;align-items:center;padding:13px 0;border-top:1px solid #edf1f5}.choice:first-of-type{border-top:0}.price{color:#377dff;font-weight:800}.input{width:100%;border:1px solid #d6dfeb;border-radius:8px;padding:11px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fields label{font-size:13px;font-weight:700}.fields label span{display:block;margin-bottom:6px}.full{grid-column:1/-1}.pay{width:100%;border:0;border-radius:9px;background:#377dff;color:#fff;padding:13px;font-weight:800;font-size:16px}.alert{background:#fff2f2;color:#c92a2a;padding:12px;border-radius:8px;margin-bottom:12px}.summary{position:sticky;top:20px}.muted{color:#718096}.total{display:flex;justify-content:space-between;font-size:20px;border-top:1px solid #e3e8ef;padding-top:16px}.desc{line-height:1.65}@media(max-width:850px){.layout{grid-template-columns:1fr}.summary{position:static}.fields{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><header><a href="{{route('events.index')}}" style="text-decoration:none;color:inherit">Net-Works Events</a></header><main class="wrap"><section class="hero"><div>{{$event->starts_at->format('l, d F Y · h:i A')}}</div><h1>{{$event->title}}</h1><div>{{$event->venue_name}} {{$event->venue_address?'· '.$event->venue_address:''}}</div></section><div class="layout"><div><section class="card"><h2>About this event</h2><div class="desc">{!! nl2br(e($event->description ?: $event->summary)) !!}</div></section>
@if($event->cover_image)<style>.hero{position:relative;overflow:hidden;min-height:360px;display:flex;flex-direction:column;justify-content:flex-end;background:#243b68}.hero .event-cover{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;z-index:0}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,22,48,.9) 0%,rgba(8,22,48,.58) 52%,rgba(8,22,48,.18) 100%);z-index:1}.hero>div,.hero>h1{position:relative;z-index:2}</style><script>document.addEventListener('DOMContentLoaded',()=>{const hero=document.querySelector('.hero'),img=document.createElement('img');img.className='event-cover';img.src=@json(url('public/'.$event->cover_image));img.alt=@json($event->title.' event header');hero.prepend(img)});</script>@endif
