@if($event->addons->count())<section class="card"><h2>2. Food & add-ons</h2>@foreach($event->addons as $addon)<div class="choice"><div><b>{{$addon->name}}</b><div class="muted">{{$addon->description}}</div><div class="price">{{$event->currency}} {{number_format((float)$addon->price,2)}} / {{str_replace('_',' ',$addon->pricing_type)}}</div></div><input class="input calc" type="number" min="0" value="0" name="addons[{{$addon->id}}]" data-price="{{$addon->price}}" data-order="{{$addon->pricing_type==='per_order'?1:0}}"></div>@endforeach</section>@endif
<section class="card"><h2>3. Booking contact & company</h2><p class="muted">These details will appear on the booking and payment record.</p><div class="fields"><label><span>Contact name *</span><input class="input" name="customer_name" value="{{old('customer_name')}}" required></label><label><span>Email *</span><input class="input" type="email" name="customer_email" value="{{old('customer_email')}}" required></label><label><span>Phone</span><input class="input" name="customer_phone" value="{{old('customer_phone')}}"></label><label><span>Company name *</span><input class="input" name="company_name" value="{{old('company_name')}}" required></label><label class="full"><span>GST number <small class="muted">(optional)</small></span><input class="input" name="gst_number" value="{{old('gst_number')}}" maxlength="30" placeholder="e.g. 19ABCDE1234F1Z5"></label>@foreach($event->fields->where('applies_to','order') as $field)<label class="{{$field->field_type==='textarea'?'full':''}}"><span>{{$field->label}} {{$field->is_required?'*':''}}</span>@if($field->field_type==='textarea')<textarea class="input" name="responses[{{$field->field_key}}]" @required($field->is_required)></textarea>@elseif($field->field_type==='select')<select class="input" name="responses[{{$field->field_key}}]" @required($field->is_required)><option value="">Select</option>@foreach($field->options??[] as $opt)<option>{{$opt}}</option>@endforeach</select>@else<input class="input" type="{{$field->field_type==='checkbox'?'checkbox':($field->field_type==='phone'?'tel':$field->field_type)}}" name="responses[{{$field->field_key}}]" value="1" @required($field->is_required)>@endif</label>@endforeach</div></section>@if($event->collect_attendee_details)<section class="card"><h2>4. Attendee details</h2><p class="muted">Enter the name, company and designation for every selected seat.</p><div id="attendee-fields"><div class="muted">Select tickets above to add attendee details.</div></div></section>@endif</div>
<aside><section class="card summary"><h2>Order summary</h2><p class="muted">Choose your seats and optional extras. Prices are calculated securely again before payment.</p><div class="total"><b>Total</b><b><span>{{$event->currency}}</span> <span id="total">0.00</span></b></div><p class="muted" id="seats">0 seats selected</p><button class="pay">Continue to secure payment</button><p class="muted" style="font-size:12px;text-align:center">Free orders confirm immediately. Paid orders use Stripe Checkout.</p></section></aside></form></div></main><script>const attendeeRequired={{$event->collect_attendee_details?'true':'false'}};const renderAttendees=()=>{if(!attendeeRequired)return;const seats=[...document.querySelectorAll('.ticket')].reduce((n,i)=>n+(+i.value||0),0),box=document.getElementById('attendee-fields'),existing={};box.querySelectorAll('input').forEach(i=>existing[i.name]=i.value);if(!seats){box.innerHTML='<div class="muted">Select tickets above to add attendee details.</div>';return}box.innerHTML=Array.from({length:seats},(_,i)=>`<div class="attendee"><h3>Attendee ${i+1}</h3><div class="fields"><label><span>Full name *</span><input class="input" name="attendees[${i}][first_name]" required></label><label><span>Company *</span><input class="input" name="attendees[${i}][company_name]" required></label><label><span>Designation *</span><input class="input" name="attendees[${i}][designation]" required></label></div></div>`).join('');box.querySelectorAll('input').forEach(i=>{if(existing[i.name])i.value=existing[i.name]})};const calc=()=>{let total=0,seats=0;document.querySelectorAll('.calc').forEach(i=>{let q=+i.value||0;if(i.classList.contains('ticket'))seats+=q;if(i.dataset.order&&q>0)q=1;total+=q*(+i.dataset.price)});document.getElementById('total').textContent=total.toFixed(2);document.getElementById('seats').textContent=seats+' seat'+(seats===1?'':'s')+' selected'};document.addEventListener('input',e=>{if(e.target.classList.contains('calc'))calc();if(e.target.classList.contains('ticket'))renderAttendees()});calc();renderAttendees();</script></body></html>
